/// <summary>
/// Class is used to get record from table <c>MCRInventTable</c> based on pricingObject parameter.
/// </summary>
internal abstract class GUPPricingAttributeMCRInventTable extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
}

Method.Source:
protected MCRInventTable getTableRecord(Common _pricingObject)
{
    SalesLine           salesLine;
    SalesQuotationLine  salesQoutationLine;
    MCRInventTable      mcrInventTable;

    Switch (_pricingObject.tableId)
    {

        case tableNum(SalesLine):
            salesLine = _pricingObject as SalesLine;
            if (salesLine.ItemId)
            {
                mcrInventTable = salesLine.inventTable().mcrInventTable();
            }
            break;

        case tableNum(SalesQuotationLine):
            salesQoutationLine = _pricingObject as SalesQuotationLine;
            if (salesQoutationLine.ItemId)
            {
                mcrInventTable = salesQoutationLine.inventTable().mcrInventTable();
            }
            break;
    }

    return mcrInventTable;
}

protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbdsRoot;

    if (_qbdsMap && _qbdsMap.exists(tableStr(MCRInventTable)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(MCRInventTable));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(MCRInventTable));

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(MCRInventTable), qbdsRoot);
        }
    }

    return qbdsRoot;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}

public GUPPricingAttributeTableFieldPath getPath()
{
    return strFmt('%1#%2_%3$%4#%5_%6$%7',
        tableStr(SalesLine),
        tableStr(InventTable),
        fieldStr(SalesLine, ItemId),
        fieldStr(InventTable, ItemId),
        tableStr(MCRInventTable),
        fieldStr(InventTable, RecId),
        fieldStr(MCRInventTable, InventTable));
}
